def transform(grid):
    g = np.array(grid, copy=True)
    h, w = g.shape

    vals, counts = np.unique(g, return_counts=True)
    bg = vals[np.argmax(counts)]

    non_bg = [v for v in vals if v != bg]
    if not non_bg:
        return g

    # The divider/wall color is the non-background color forming the largest
    # connected line structure.
    wall = None
    best = -1
    for v in non_bg:
        n = int(np.sum(g == v))
        if n > best:
            best = n
            wall = v

    out = g.copy()
    open_cell = (g != wall)
    seen = np.zeros((h, w), dtype=bool)
    dirs4 = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    dirs8 = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc]

    for sr in range(h):
        for sc in range(w):
            if seen[sr, sc] or not open_cell[sr, sc]:
                continue

            comp = []
            q = [(sr, sc)]
            seen[sr, sc] = True
            qi = 0
            while qi < len(q):
                r, c = q[qi]
                qi += 1
                comp.append((r, c))
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and open_cell[nr, nc] and not seen[nr, nc]:
                        seen[nr, nc] = True
                        q.append((nr, nc))

            in_comp = np.zeros((h, w), dtype=bool)
            for r, c in comp:
                in_comp[r, c] = True

            boundary = []
            for r, c in comp:
                b = (r == 0 or r == h - 1 or c == 0 or c == w - 1)
                if not b:
                    for dr, dc in dirs8:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == wall:
                            b = True
                            break
                if b:
                    boundary.append((r, c))

            dist = -np.ones((h, w), dtype=int)
            frontier = []
            for p in boundary:
                dist[p] = 0
                frontier.append(p)

            qi = 0
            while qi < len(frontier):
                r, c = frontier[qi]
                qi += 1
                for dr, dc in dirs4:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and in_comp[nr, nc] and dist[nr, nc] < 0:
                        dist[nr, nc] = dist[r, c] + 1
                        frontier.append((nr, nc))

            by_depth = {}
            for r, c in comp:
                col = g[r, c]
                if col != bg and col != wall:
                    d = dist[r, c]
                    if d not in by_depth:
                        by_depth[d] = col

            if not by_depth:
                continue

            palette = []
            if 0 not in by_depth:
                palette.append(bg)
            for d in sorted(by_depth):
                palette.append(by_depth[d])

            for r, c in comp:
                out[r, c] = palette[dist[r, c] % len(palette)]

    return out

def transform(grid):
    h, w = grid.shape

    vals, counts = np.unique(grid, return_counts=True)
    bg = vals[np.argmax(counts)]

    divider = None
    best_count = -1
    for v, c in zip(vals, counts):
        if v != bg and c > best_count:
            divider = v
            best_count = c

    out = grid.copy()
    seen = np.zeros((h, w), dtype=bool)

    for sr in range(h):
        for sc in range(w):
            if seen[sr, sc] or grid[sr, sc] == divider:
                continue

            stack = [(sr, sc)]
            seen[sr, sc] = True
            cells = []

            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if not seen[nr, nc] and grid[nr, nc] != divider:
                            seen[nr, nc] = True
                            stack.append((nr, nc))

            seeds = [(r, c, grid[r, c]) for r, c in cells
                     if grid[r, c] != bg and grid[r, c] != divider]
            if not seeds:
                continue

            r0 = min(r for r, _ in cells)
            r1 = max(r for r, _ in cells)
            c0 = min(c for _, c in cells)
            c1 = max(c for _, c in cells)

            by_depth = {}
            for r, c, color in seeds:
                d = min(r - r0, r1 - r, c - c0, c1 - c)
                if d not in by_depth:
                    by_depth[d] = color

            max_seed_depth = max(by_depth)
            cycle = [by_depth.get(d, bg) for d in range(max_seed_depth + 1)]

            for r, c in cells:
                d = min(r - r0, r1 - r, c - c0, c1 - c)
                out[r, c] = cycle[d % len(cycle)]

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    vals, counts = np.unique(grid, return_counts=True)
    bg = vals[np.argmax(counts)]

    sep = None
    best = -1
    for v, c in zip(vals, counts):
        if v != bg and c > best:
            sep = v
            best = c
    if sep is None:
        return out

    seen = np.zeros((h, w), dtype=bool)

    for sr in range(h):
        for sc in range(w):
            if seen[sr, sc] or grid[sr, sc] == sep:
                continue

            stack = [(sr, sc)]
            seen[sr, sc] = True
            cells = []
            cellset = set()

            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                cellset.add((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < h and 0 <= nc < w
                        and not seen[nr, nc]
                        and grid[nr, nc] != sep
                    ):
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            clues = []
            for r, c in cells:
                if grid[r, c] != bg and grid[r, c] != sep:
                    clues.append((r, c, grid[r, c]))
            if not clues:
                continue

            layer = {}
            q = []
            for r, c in cells:
                boundary = False
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if not (0 <= nr < h and 0 <= nc < w) or (nr, nc) not in cellset:
                            boundary = True
                if boundary:
                    layer[(r, c)] = 0
                    q.append((r, c))

            qi = 0
            while qi < len(q):
                r, c = q[qi]
                qi += 1
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if (nr, nc) in cellset and (nr, nc) not in layer:
                            layer[(nr, nc)] = layer[(r, c)] + 1
                            q.append((nr, nc))

            layer_colors = {}
            for r, c, color in clues:
                layer_colors[layer[(r, c)]] = color

            period = max(layer_colors) + 1
            seq = [bg] * period
            for k, color in layer_colors.items():
                seq[k] = color

            for r, c in cells:
                out[r, c] = seq[layer[(r, c)] % period]

    return out

def transform(grid):
    out = grid.copy()
    h, w = out.shape

    out[out == 3] = 8
    centers = {}

    for r in range(h):
        c = 0
        while c < w:
            if grid[r, c] == 7:
                start = c
                while c < w and grid[r, c] == 7:
                    c += 1
                if c - start == 3:
                    mid = start + 1
                    centers.setdefault(r, []).append(mid)
                    for cc in range(start, c):
                        out[r, cc] = 6 if cc == mid else 8
                    for rr in (r - 1, r + 1):
                        if 0 <= rr < h and grid[rr, mid] != 0:
                            out[rr, mid] = 6
                continue
            c += 1

    for r in range(0, h, 2):
        c = 0
        while c < w:
            if grid[r, c] == 0:
                c += 1
                continue

            lo = c
            while c < w and grid[r, c] != 0:
                c += 1
            hi = c - 1

            above = [x for x in centers.get(r - 1, []) if lo <= x <= hi and grid[r, x] != 0]
            below = [x for x in centers.get(r + 1, []) if lo <= x <= hi and grid[r, x] != 0]

            sides = []
            doubled = bool(above and below)

            if above and below:
                mina, maxa = min(above), max(above)
                minb, maxb = min(below), max(below)

                if mina < minb and maxa > maxb:
                    sides = ["left", "right"]
                elif mina > minb and maxa < maxb:
                    sides = []
                elif mina < minb and maxa <= maxb:
                    sides = ["left"]
                elif mina >= minb and maxa > maxb:
                    sides = ["right"]

            elif above and not below:
                sides = ["left"]
                if hi == w - 1:
                    sides.append("right")

            elif not above and not below:
                if grid[r, lo] == 3:
                    sides.append("left")
                if hi != lo and grid[r, hi] == 3:
                    sides.append("right")

            for side in sides:
                if side == "left":
                    out[r, lo] = 3
                    if doubled and lo == 0 and hi == w - 1 and lo + 1 <= hi:
                        out[r, lo + 1] = 3
                else:
                    out[r, hi] = 3
                    if doubled and lo == 0 and hi == w - 1 and hi - 1 >= lo:
                        out[r, hi - 1] = 3

    return out

def transform(grid):
    g = grid.copy()
    h, w = g.shape

    out = g.copy()
    out[out == 3] = 8
    out[out == 7] = 8

    for r in range(h):
        for c in range(1, w - 1):
            if g[r, c - 1] == 7 and g[r, c] == 7 and g[r, c + 1] == 7:
                for rr in (r - 1, r, r + 1):
                    if 0 <= rr < h:
                        out[rr, c] = 6

    seen = np.zeros((h, w), dtype=bool)

    for sr in range(h):
        for sc in range(w):
            if seen[sr, sc] or out[sr, sc] in (0, 6):
                continue

            stack = [(sr, sc)]
            seen[sr, sc] = True
            comp = []
            sources = []

            while stack:
                r, c = stack.pop()
                comp.append((r, c))
                if g[r, c] == 3:
                    sources.append((r, c))

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and out[nr, nc] not in (0, 6):
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            if not sources:
                continue

            bottom_r = max(r for r, c in comp)
            cols = sorted(c for r, c in comp if r == bottom_r)

            runs = []
            start = cols[0]
            prev = cols[0]
            for c in cols[1:]:
                if c == prev + 1:
                    prev = c
                else:
                    runs.append((start, prev))
                    start = prev = c
            runs.append((start, prev))

            mean_source = sum(c for r, c in sources) / len(sources)
            best = None

            for a, b in runs:
                left_open = a == 0 or out[bottom_r, a - 1] == 0
                right_open = b == w - 1 or out[bottom_r, b + 1] == 0

                left_score = (1 if left_open else 0, -abs(mean_source - a))
                right_score = (1 if right_open else 0, -abs(mean_source - b))

                if best is None or left_score > best[0]:
                    best = (left_score, a, b, -1)
                if right_score > best[0]:
                    best = (right_score, a, b, 1)

            _, a, b, side = best
            n = len(sources)

            if side < 0:
                for c in range(a, min(b + 1, a + n)):
                    out[bottom_r, c] = 3
            else:
                for c in range(b, max(a - 1, b - n), -1):
                    out[bottom_r, c] = 3

    return out

def transform(grid):
    out = grid.copy()
    h, w = out.shape

    centers_by_row = {}
    for r in range(h):
        centers = []
        c = 0
        while c < w:
            if grid[r, c] == 7:
                start = c
                while c < w and grid[r, c] == 7:
                    c += 1
                end = c
                if end - start == 3:
                    centers.append(start + 1)
            else:
                c += 1
        if centers:
            centers_by_row[r] = centers

    out[out == 3] = 8
    out[out == 7] = 8

    for r, centers in centers_by_row.items():
        for c in centers:
            out[r, c] = 6
            if r - 1 >= 0 and out[r - 1, c] != 0:
                out[r - 1, c] = 6
            if r + 1 < h and out[r + 1, c] != 0:
                out[r + 1, c] = 6

    def put_left(r):
        if w > 0 and out[r, 0] != 0:
            out[r, 0] = 3
        if w > 1 and out[r, 1] != 0:
            out[r, 1] = 3

    def put_right(r):
        if w > 0 and out[r, w - 1] != 0:
            out[r, w - 1] = 3
        if w > 1 and out[r, w - 2] != 0:
            out[r, w - 2] = 3

    candidate_rows = [
        r for r in range(h)
        if r not in centers_by_row and any(grid[r, c] in (3, 8) for c in range(w))
    ]

    for r in candidate_rows:
        above = centers_by_row.get(r - 1, [])
        below = centers_by_row.get(r + 1, [])

        side = None
        if len(above) > len(below):
            side = "both"
        elif len(above) == len(below) and len(above) > 0:
            if sum(below) > sum(above):
                side = "left"
            elif sum(below) < sum(above):
                side = "right"

        if side is None:
            continue

        zero_cols = [c for c in range(w) if grid[r, c] == 0]
        is_last_end = len(above) > 0 and len(below) == 0

        if side == "left":
            put_left(r)
        elif side == "right":
            put_right(r)
        else:
            if zero_cols:
                if is_last_end and grid[r, 0] != 3 and grid[r, w - 1] != 3:
                    for z in zero_cols:
                        if z + 1 < w and out[r, z + 1] != 0:
                            out[r, z + 1] = 3
                    if out[r, w - 1] != 0:
                        out[r, w - 1] = 3
                else:
                    if grid[r, 0] == 3 and out[r, 0] != 0:
                        out[r, 0] = 3
                    if grid[r, w - 1] == 3 and out[r, w - 1] != 0:
                        out[r, w - 1] = 3
                    for z in zero_cols:
                        if z - 1 >= 0 and out[r, z - 1] != 0:
                            out[r, z - 1] = 3
            elif is_last_end and grid[r, 0] != 3 and grid[r, w - 1] != 3:
                if out[r, 0] != 0:
                    out[r, 0] = 3
                if out[r, w - 1] != 0:
                    out[r, w - 1] = 3
            else:
                put_left(r)
                put_right(r)

    return out

def transform(grid):
    bg = np.bincount(grid.ravel()).argmax()
    vals = [v for v in np.unique(grid) if v != bg]
    fg = vals[0]
    H, W = grid.shape

    def comps(mask):
        seen = np.zeros(mask.shape, dtype=bool)
        out = []
        h, w = mask.shape
        for r in range(h):
            for c in range(w):
                if mask[r, c] and not seen[r, c]:
                    q = [(r, c)]
                    seen[r, c] = True
                    cells = []
                    for x, y in q:
                        cells.append((x, y))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w and mask[nx, ny] and not seen[nx, ny]:
                                seen[nx, ny] = True
                                q.append((nx, ny))
                    out.append(cells)
        return out

    def bbox(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    def center(cells):
        return (sum(r for r, c in cells) / len(cells), sum(c for r, c in cells) / len(cells))

    holes = []
    for cells in comps(grid == bg):
        if any(r == 0 or c == 0 or r == H - 1 or c == W - 1 for r, c in cells):
            continue
        holes.append({"cells": set(cells), "bbox": bbox(cells), "children": [], "islands": []})

    def contains(a, b):
        ar0, ar1, ac0, ac1 = a["bbox"]
        br0, br1, bc0, bc1 = b["bbox"]
        return a is not b and ar0 <= br0 and br1 <= ar1 and ac0 <= bc0 and bc1 <= ac1

    roots = []
    for h in holes:
        ps = [p for p in holes if contains(p, h)]
        if ps:
            p = min(ps, key=lambda x: (x["bbox"][1] - x["bbox"][0] + 1) * (x["bbox"][3] - x["bbox"][2] + 1))
            h["parent"] = p
            p["children"].append(h)
        else:
            h["parent"] = None
            roots.append(h)

    def inside(comp, h):
        r0, r1, c0, c1 = h["bbox"]
        a, b, d, e = bbox(comp)
        return r0 <= a and b <= r1 and c0 <= d and e <= c1

    def adjacent(comp, h):
        s = set(comp)
        for r, c in h["cells"]:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                if (r + dr, c + dc) in s:
                    return True
        return False

    top = []
    for comp in comps(grid == fg):
        hs = [h for h in holes if inside(comp, h)]
        if not hs:
            top.append(comp)
            continue
        h = min(hs, key=lambda x: (x["bbox"][1] - x["bbox"][0] + 1) * (x["bbox"][3] - x["bbox"][2] + 1))
        if not any(adjacent(comp, ch) for ch in h["children"]):
            h["islands"].append(comp)

    def frame(h, w):
        a = np.full((h, w), bg, dtype=int)
        a[0, :] = fg
        a[-1, :] = fg
        a[:, 0] = fg
        a[:, -1] = fg
        return a

    def render_leaf(islands):
        pts = [center(x) for x in islands]
        n = max(1, len(pts))
        if n == 1:
            a = frame(5, 5)
            a[2, 2] = fg
            return a
        vert = (max(p[0] for p in pts) - min(p[0] for p in pts)) > (max(p[1] for p in pts) - min(p[1] for p in pts))
        if vert:
            a = frame(2 * n + 3, 5)
            for i, _ in enumerate(sorted(pts)):
                a[2 + 2 * i, 2] = fg
        else:
            a = frame(5, 2 * n + 3)
            for i, _ in enumerate(sorted(pts, key=lambda p: p[1])):
                a[2, 2 + 2 * i] = fg
        return a

    def render_hole(h):
        if not h["children"]:
            return render_leaf(h["islands"])
        items = []
        for ch in h["children"]:
            items.append((center(ch["cells"]), render_hole(ch)))
        for isl in h["islands"]:
            items.append((center(isl), np.array([[fg]], dtype=int)))
        vert = (max(p[0] for p, a in items) - min(p[0] for p, a in items)) > (max(p[1] for p, a in items) - min(p[1] for p, a in items))
        if vert:
            items.sort(key=lambda x: x[0][0])
            ih = sum(a.shape[0] for p, a in items) + len(items) - 1
            iw = max(a.shape[1] for p, a in items)
            out = frame(ih + 4, iw + 4)
            r = 2
            for p, a in items:
                c = 2 + (iw - a.shape[1]) // 2
                out[r:r + a.shape[0], c:c + a.shape[1]] = a
                r += a.shape[0] + 1
        else:
            items.sort(key=lambda x: x[0][1])
            ih = max(a.shape[0] for p, a in items)
            iw = sum(a.shape[1] for p, a in items) + len(items) - 1
            out = frame(ih + 4, iw + 4)
            c = 2
            for p, a in items:
                r = 2 + (ih - a.shape[0]) // 2
                out[r:r + a.shape[0], c:c + a.shape[1]] = a
                c += a.shape[1] + 1
        return out

    root_pieces = [(center(r["cells"]), render_hole(r)) for r in roots]
    if root_pieces:
        r0 = min(r["bbox"][0] for r in roots)
        r1 = max(r["bbox"][1] for r in roots)
        c0 = min(r["bbox"][2] for r in roots)
        c1 = max(r["bbox"][3] for r in roots)
    else:
        r0, r1, c0, c1 = 0, H - 1, 0, W - 1

    extra = []
    for comp in top:
        if len(comp) <= 1:
            continue
        a, b, c, d = bbox(comp)
        cy = (a + b) / 2
        cx = (c + d) / 2
        if c > c1 and r0 <= cy <= r1:
            extra.append(((cy, cx), np.array([[fg]], dtype=int)))

    pieces = sorted(root_pieces, key=lambda x: x[0][1])
    if not pieces:
        return render_leaf([max(comps(grid == fg), key=len)])
    out = pieces[0][1]
    for p, a in pieces[1:]:
        h = max(out.shape[0], a.shape[0])
        w = out.shape[1] + a.shape[1]
        b = np.full((h, w), bg, dtype=int)
        b[(h - out.shape[0]) // 2:(h - out.shape[0]) // 2 + out.shape[0], :out.shape[1]] = out
        b[(h - a.shape[0]) // 2:(h - a.shape[0]) // 2 + a.shape[0], out.shape[1]:] = a
        out = b

    if extra:
        col = out.shape[1] + 1
        h = out.shape[0]
        b = np.full((h, col + 2), bg, dtype=int)
        b[:, :out.shape[1]] = out
        scale = (h - 1) / max(1, (r1 - r0))
        for (cy, cx), a in extra[:1]:
            rr = int(round((cy - r0) * scale))
            rr = max(0, min(h - 1, rr))
            b[rr, col] = fg
        out = b

    return out

def transform(grid):
    h, w = grid.shape
    vals, counts = np.unique(grid, return_counts=True)
    bg = vals[np.argmax(counts)]
    fg = vals[0] if vals[0] != bg else vals[1]

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def comps_of(color):
        seen = np.zeros((h, w), dtype=bool)
        comps = []
        for r in range(h):
            for c in range(w):
                if seen[r, c] or grid[r, c] != color:
                    continue
                q = [(r, c)]
                seen[r, c] = True
                pts = []
                for x, y in q:
                    pts.append((x, y))
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and not seen[nx, ny] and grid[nx, ny] == color:
                            seen[nx, ny] = True
                            q.append((nx, ny))
                arr = np.array(pts)
                touch = np.any(
                    (arr[:, 0] == 0) | (arr[:, 0] == h - 1) |
                    (arr[:, 1] == 0) | (arr[:, 1] == w - 1)
                )
                comps.append({
                    "pts": pts,
                    "bbox": (int(arr[:, 0].min()), int(arr[:, 0].max()),
                             int(arr[:, 1].min()), int(arr[:, 1].max())),
                    "center": (float(arr[:, 0].mean()), float(arr[:, 1].mean())),
                    "touch": bool(touch),
                })
        return comps

    holes = [c for c in comps_of(bg) if not c["touch"]]
    fg_comps = comps_of(fg)

    def inside_bbox(inner, outer):
        a, b, c, d = inner
        e, f, g, i = outer
        return e <= a and b <= f and g <= c and d <= i

    for i, hole in enumerate(holes):
        parent = None
        parent_area = None
        for j, other in enumerate(holes):
            if i == j:
                continue
            if inside_bbox(hole["bbox"], other["bbox"]):
                area = (other["bbox"][1] - other["bbox"][0] + 1) * (other["bbox"][3] - other["bbox"][2] + 1)
                if parent is None or area < parent_area:
                    parent = j
                    parent_area = area
        hole["parent"] = parent
        hole["children"] = []

    dots = []
    for comp in fg_comps:
        contains_hole = False
        for hole in holes:
            if inside_bbox(hole["bbox"], comp["bbox"]):
                contains_hole = True
                break
        if not contains_hole:
            dots.append({"type": "dot", "bbox": comp["bbox"], "center": comp["center"]})

    objects_for_hole = [[] for _ in holes]
    top_objects = []

    for i, hole in enumerate(holes):
        obj = {"type": "hole", "idx": i, "bbox": hole["bbox"], "center": hole["center"]}
        if hole["parent"] is None:
            top_objects.append(obj)
        else:
            objects_for_hole[hole["parent"]].append(obj)

    for dot in dots:
        parent = None
        parent_area = None
        r, c = dot["center"]
        for i, hole in enumerate(holes):
            r1, r2, c1, c2 = hole["bbox"]
            if r1 <= r <= r2 and c1 <= c <= c2:
                area = (r2 - r1 + 1) * (c2 - c1 + 1)
                if parent is None or area < parent_area:
                    parent = i
                    parent_area = area
        if parent is None:
            top_objects.append(dot)
        else:
            objects_for_hole[parent].append(dot)

    def render_obj(obj):
        if obj["type"] == "dot":
            return np.array([[fg]], dtype=int)
        return render_hole(obj["idx"])

    def pack(children, framed):
        rendered = [(child, render_obj(child)) for child in children]
        if not rendered:
            inner = np.full((1, 1), bg, dtype=int)
            if not framed:
                return inner
            out = np.full((3, 3), fg, dtype=int)
            out[1, 1] = bg
            return out

        if len(rendered) == 1:
            horizontal = True
        else:
            rs = [x[0]["center"][0] for x in rendered]
            cs = [x[0]["center"][1] for x in rendered]
            horizontal = (max(cs) - min(cs)) >= (max(rs) - min(rs))

        if horizontal:
            rendered.sort(key=lambda x: x[0]["center"][1])
            ih = max(a.shape[0] for _, a in rendered)
            iw = sum(a.shape[1] for _, a in rendered) + max(0, len(rendered) - 1)
            inner = np.full((ih, iw), bg, dtype=int)
            x = 0
            for _, arr in rendered:
                y = (ih - arr.shape[0]) // 2
                inner[y:y + arr.shape[0], x:x + arr.shape[1]] = arr
                x += arr.shape[1] + 1
        else:
            rendered.sort(key=lambda x: x[0]["center"][0])
            ih = sum(a.shape[0] for _, a in rendered) + max(0, len(rendered) - 1)
            iw = max(a.shape[1] for _, a in rendered)
            inner = np.full((ih, iw), bg, dtype=int)
            y = 0
            for _, arr in rendered:
                x = (iw - arr.shape[1]) // 2
                inner[y:y + arr.shape[0], x:x + arr.shape[1]] = arr
                y += arr.shape[0] + 1

        if not framed:
            return inner

        out = np.full((inner.shape[0] + 4, inner.shape[1] + 4), bg, dtype=int)
        out[0, :] = fg
        out[-1, :] = fg
        out[:, 0] = fg
        out[:, -1] = fg
        out[2:2 + inner.shape[0], 2:2 + inner.shape[1]] = inner
        return out

    def render_hole(i):
        return pack(objects_for_hole[i], True)

    if len(top_objects) == 1:
        return render_obj(top_objects[0])

    top_objects.sort(key=lambda x: x["center"][1])
    rendered = [(obj, render_obj(obj)) for obj in top_objects]
    out_h = max(arr.shape[0] for _, arr in rendered)
    out_w = sum(arr.shape[1] for _, arr in rendered) + len(rendered)
    out = np.full((out_h, out_w), bg, dtype=int)

    min_r = min(obj["bbox"][0] for obj, _ in rendered)
    max_r = max(obj["bbox"][1] for obj, _ in rendered)
    denom = max(1, max_r - min_r)

    x = 0
    for obj, arr in rendered:
        if arr.shape[0] == out_h:
            y = 0
        else:
            cy = int(round((obj["center"][0] - min_r) * (out_h - 1) / denom))
            y = max(0, min(out_h - arr.shape[0], cy - arr.shape[0] // 2))
        out[y:y + arr.shape[0], x:x + arr.shape[1]] = arr
        x += arr.shape[1] + 1

    return out

def transform(grid):
    bg = int(np.bincount(grid.ravel(), minlength=10).argmax())
    counts = np.bincount(grid.ravel(), minlength=10)
    non_bg = [c for c in range(10) if c != bg and counts[c] > 0]
    border = max(non_bg, key=lambda c: counts[c])

    allowed = {border}
    for c in non_bg:
        if counts[c] >= 4:
            allowed.add(c)

    valid = np.zeros(grid.shape, dtype=bool)
    for c in allowed:
        valid |= (grid == c)

    R, C = grid.shape
    seen = np.zeros_like(valid, dtype=bool)
    rects = []

    def edge_ok(a):
        return (
            np.all(a[0, :] == border) or
            np.all(a[-1, :] == border) or
            np.all(a[:, 0] == border) or
            np.all(a[:, -1] == border)
        )

    for sr in range(R):
        for sc in range(C):
            if not valid[sr, sc] or seen[sr, sc]:
                continue

            q = [(sr, sc)]
            seen[sr, sc] = True
            cells = []
            for r, c in q:
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C and valid[nr, nc] and not seen[nr, nc]:
                        seen[nr, nc] = True
                        q.append((nr, nc))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            submask = valid[r0:r1 + 1, c0:c1 + 1]

            if np.all(submask):
                a = grid[r0:r1 + 1, c0:c1 + 1]
                if a.shape[0] >= 2 and a.shape[1] >= 2 and border in a and edge_ok(a):
                    rects.append((r0, c0, a.copy()))
                continue

            rem = submask.copy()
            while np.any(rem):
                best = None
                h0, w0 = rem.shape
                pref = np.pad(rem.astype(int), ((1, 0), (1, 0))).cumsum(0).cumsum(1)

                for a0 in range(h0):
                    for b0 in range(w0):
                        if not rem[a0, b0]:
                            continue
                        for a1 in range(a0 + 1, h0):
                            for b1 in range(b0 + 1, w0):
                                area = (a1 - a0 + 1) * (b1 - b0 + 1)
                                s = pref[a1 + 1, b1 + 1] - pref[a0, b1 + 1] - pref[a1 + 1, b0] + pref[a0, b0]
                                if s != area:
                                    continue
                                a = grid[r0 + a0:r0 + a1 + 1, c0 + b0:c0 + b1 + 1]
                                if border in a and edge_ok(a):
                                    if best is None or area > best[0]:
                                        best = (area, a0, a1, b0, b1)

                if best is None:
                    break

                _, a0, a1, b0, b1 = best
                rects.append((r0 + a0, c0 + b0, grid[r0 + a0:r0 + a1 + 1, c0 + b0:c0 + b1 + 1].copy()))
                rem[a0:a1 + 1, b0:b1 + 1] = False

    rects.sort(key=lambda x: (x[0], x[1]))
    pieces = [x[2] for x in rects]
    if not pieces:
        return grid.copy()

    area = sum(p.size for p in pieces)
    maxh = max(p.shape[0] for p in pieces)
    maxw = max(p.shape[1] for p in pieces)

    candidates = []
    for h in range(maxh, area + 1):
        if area % h == 0:
            w = area // h
            if w >= maxw:
                candidates.append((h, w))
    candidates.sort(key=lambda hw: (hw[0] > hw[1], abs(hw[1] / hw[0] - 1.6)))

    solution = None

    def fits_boundary(p, y, x, H, W):
        h, w = p.shape
        if y == 0 and not np.all(p[0, :] == border):
            return False
        if y + h == H and not np.all(p[-1, :] == border):
            return False
        if x == 0 and not np.all(p[:, 0] == border):
            return False
        if x + w == W and not np.all(p[:, -1] == border):
            return False
        return True

    for H, W in candidates:
        canvas = np.full((H, W), -1, dtype=int)
        used = [False] * len(pieces)

        def search():
            pos = np.argwhere(canvas == -1)
            if len(pos) == 0:
                return True
            y, x = pos[0]
            for i, p in enumerate(pieces):
                if used[i]:
                    continue
                h, w = p.shape
                if y + h > H or x + w > W:
                    continue
                if np.any(canvas[y:y + h, x:x + w] != -1):
                    continue
                if not fits_boundary(p, y, x, H, W):
                    continue
                used[i] = True
                canvas[y:y + h, x:x + w] = p
                if search():
                    return True
                canvas[y:y + h, x:x + w] = -1
                used[i] = False
            return False

        if search():
            solution = canvas.copy()
            break

    if solution is None:
        return grid.copy()

    H, W = solution.shape
    if H > R or W > C:
        return solution

    out = np.full_like(grid, bg)
    top = (R - H + 1) // 2
    centers = [c + p.shape[1] / 2 for _, c, p in rects]
    left = int(round(sum(centers) / len(centers) - W / 2))
    left = max(0, min(C - W, left))
    out[top:top + H, left:left + W] = solution
    return out

def transform(grid):
    g = np.array(grid)
    H, W = g.shape

    vals, cnts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(cnts)])
    counts = {int(v): int(c) for v, c in zip(vals, cnts)}
    non_bg = [int(v) for v in vals if int(v) != bg]
    frame = max(non_bg, key=lambda x: counts[x])

    marker = None
    marker_corner = None
    for c in non_bg:
        if c == frame:
            continue
        pts = np.argwhere(g == c)
        if len(pts) == 3:
            r0, c0 = pts.min(axis=0)
            r1, c1 = pts.max(axis=0)
            if r1 - r0 == 1 and c1 - c0 == 1:
                present = {(int(r), int(col)) for r, col in pts}
                for rr in (int(r0), int(r1)):
                    for cc in (int(c0), int(c1)):
                        if (rr, cc) not in present:
                            marker = c
                            marker_corner = (rr, cc, rr - int(r0), cc - int(c0))
                            break
                    if marker is not None:
                        break
        if marker is not None:
            break

    keep = set(non_bg)
    if marker is not None:
        keep.remove(marker)

    mask = np.zeros(g.shape, dtype=bool)
    for c in keep:
        mask |= (g == c)

    seen = np.zeros(g.shape, dtype=bool)
    pieces = []

    for r in range(H):
        for c in range(W):
            if not mask[r, c] or seen[r, c]:
                continue

            stack = [(r, c)]
            seen[r, c] = True
            pts = []
            while stack:
                x, y = stack.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W and mask[nx, ny] and not seen[nx, ny]:
                        seen[nx, ny] = True
                        stack.append((nx, ny))

            rs = [p[0] for p in pts]
            cs = [p[1] for p in pts]
            sub = g[min(rs):max(rs) + 1, min(cs):max(cs) + 1]
            pat = np.full(sub.shape, -1, dtype=int)
            for k in keep:
                pat[sub == k] = k

            for _ in range(pat.size):
                changed = False
                for i in range(pat.shape[0]):
                    for j in range(pat.shape[1]):
                        if pat[i, j] != -1:
                            continue

                        row = pat[i, pat[i] != -1]
                        col = pat[pat[:, j] != -1, j]
                        val = None

                        if len(row) and np.all(row == row[0]):
                            val = int(row[0])
                        elif len(col):
                            fcnt = np.sum(col == frame)
                            if fcnt >= len(col) - fcnt or i in (0, pat.shape[0] - 1) or j in (0, pat.shape[1] - 1):
                                val = frame
                            elif np.all(col == col[0]):
                                val = int(col[0])

                        if val is None and len(row):
                            vv, ccnt = np.unique(row, return_counts=True)
                            val = int(vv[np.argmax(ccnt)])
                        if val is None:
                            val = frame

                        pat[i, j] = val
                        changed = True
                if not changed:
                    break

            pieces.append(pat)

    n = len(pieces)
    total = sum(p.size for p in pieces)
    maxh = max(p.shape[0] for p in pieces)
    maxw = max(p.shape[1] for p in pieces)

    dims = []
    for h in range(maxh, total + 1):
        if total % h == 0:
            w = total // h
            if w >= maxw:
                dims.append((h, w))
    dims.sort(key=lambda x: (abs(x[0] - x[1]), x[0] * x[1]))

    order = sorted(range(n), key=lambda i: -pieces[i].size)
    solutions = []

    def boundary_ok(p, x, y, oh, ow):
        ph, pw = p.shape
        if x == 0 and np.any(p[0, :] != frame):
            return False
        if x + ph == oh and np.any(p[-1, :] != frame):
            return False
        if y == 0 and np.any(p[:, 0] != frame):
            return False
        if y + pw == ow and np.any(p[:, -1] != frame):
            return False
        return True

    def search(oh, ow):
        occ = np.zeros((oh, ow), dtype=bool)
        loc = [None] * n
        used = [False] * n

        def rec(k):
            if solutions:
                return
            if k == n:
                canvas = np.full((oh, ow), frame, dtype=int)
                for i, (x, y) in enumerate(loc):
                    p = pieces[i]
                    canvas[x:x + p.shape[0], y:y + p.shape[1]] = p
                if (np.all(canvas[0, :] == frame) and np.all(canvas[-1, :] == frame) and
                        np.all(canvas[:, 0] == frame) and np.all(canvas[:, -1] == frame)):
                    solutions.append(canvas)
                return

            empties = np.argwhere(~occ)
            if len(empties) == 0:
                return
            x0, y0 = empties[0]

            for idx in order:
                if used[idx]:
                    continue
                p = pieces[idx]
                ph, pw = p.shape
                for x in range(max(0, x0 - ph + 1), min(x0, oh - ph) + 1):
                    y = y0
                    if y + pw > ow:
                        continue
                    if not boundary_ok(p, x, y, oh, ow):
                        continue
                    if np.any(occ[x:x + ph, y:y + pw]):
                        continue
                    occ[x:x + ph, y:y + pw] = True
                    used[idx] = True
                    loc[idx] = (x, y)
                    rec(k + 1)
                    loc[idx] = None
                    used[idx] = False
                    occ[x:x + ph, y:y + pw] = False

        rec(0)

    for d in dims:
        search(*d)
        if solutions:
            break

    if not solutions:
        return g.copy()

    obj = solutions[0]
    oh, ow = obj.shape

    if marker_corner is not None:
        mr, mc, cr, cc = marker_corner
        if cr == 0 and cc == 0:
            ox, oy = mr - oh + 1, mc - ow + 1
        elif cr == 0 and cc == 1:
            ox, oy = mr - oh + 1, mc
        elif cr == 1 and cc == 0:
            ox, oy = mr, mc - ow + 1
        else:
            ox, oy = mr, mc
    else:
        ox, oy = (H - oh) // 2, (W - ow) // 2

    out = np.full((H, W), bg, dtype=int)
    out[ox:ox + oh, oy:oy + ow] = obj
    return out

def transform(grid):
    g = np.array(grid)
    R, C = g.shape

    vals, counts = np.unique(g, return_counts=True)
    bg = vals[np.argmax(counts)]
    count = {vals[i]: counts[i] for i in range(len(vals))}

    keep = [v for v in vals if v != bg and count[v] >= 4]
    noise = [v for v in vals if v != bg and count[v] < 4]
    if len(keep) == 0:
        return g.copy()

    mask = np.isin(g, keep)
    seen = np.zeros((R, C), dtype=bool)
    pieces = []

    for r in range(R):
        for c in range(C):
            if not mask[r, c] or seen[r, c]:
                continue

            q = [(r, c)]
            seen[r, c] = True
            cells = []
            for x, y in q:
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < R and 0 <= ny < C and mask[nx, ny] and not seen[nx, ny]:
                        seen[nx, ny] = True
                        q.append((nx, ny))

            rs = [x for x, y in cells]
            cs = [y for x, y in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)

            arr = np.full((r1 - r0 + 1, c1 - c0 + 1), bg, dtype=g.dtype)
            for x, y in cells:
                arr[x - r0, y - c0] = g[x, y]

            anchored = False
            for x, y in cells:
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < R and 0 <= ny < C and g[nx, ny] in noise:
                        anchored = True

            pieces.append((arr, r0, c0, anchored))

    total_area = sum(p[0].size for p in pieces)
    max_h = max(p[0].shape[0] for p in pieces)
    max_w = max(p[0].shape[1] for p in pieces)

    dims = []
    for h in range(1, R + 1):
        if total_area % h == 0:
            w = total_area // h
            if w <= C and h >= max_h and w >= max_w:
                dims.append((h, w))

    best_key = None
    best_out = None

    for H, W in dims:
        board = np.full((H, W), -1, dtype=int)
        used = [False] * len(pieces)
        placed = []
        order = sorted(range(len(pieces)), key=lambda i: -pieces[i][0].size)
        searched = [0]

        def score_solution():
            nonlocal best_key, best_out

            packed = np.full((H, W), bg, dtype=g.dtype)
            loc = {}
            for idx, x, y in placed:
                p = pieces[idx][0]
                packed[x:x + p.shape[0], y:y + p.shape[1]] = p
                loc[idx] = (x, y)

            anchors = [i for i, p in enumerate(pieces) if p[3]]
            origins = []
            for i in anchors:
                x, y = loc[i]
                origins.append((pieces[i][1] - x, pieces[i][2] - y))

            if not origins:
                origins = [(x, y) for x in range(R - H + 1) for y in range(C - W + 1)]

            for ox, oy in origins:
                if ox < 0 or oy < 0 or ox + H > R or oy + W > C:
                    continue

                hits = 0
                for i in anchors:
                    x, y = loc[i]
                    if ox + x == pieces[i][1] and oy + y == pieces[i][2]:
                        hits += 1

                sub = g[ox:ox + H, oy:oy + W]
                match = int(((packed != bg) & (packed == sub)).sum())

                cont = 0
                for x in range(H):
                    for y in range(W):
                        if packed[x, y] == bg:
                            continue
                        if x + 1 < H and packed[x + 1, y] == packed[x, y]:
                            cont += 1
                        if y + 1 < W and packed[x, y + 1] == packed[x, y]:
                            cont += 1

                center_penalty = abs((R - H) / 2 - ox) + abs((C - W) / 2 - oy)
                key = (hits, match, cont, -center_penalty)

                if best_key is None or key > best_key:
                    out = np.full_like(g, bg)
                    out[ox:ox + H, oy:oy + W] = packed
                    best_key = key
                    best_out = out

        def backtrack():
            if searched[0] > 50000:
                return

            pos = None
            for x in range(H):
                for y in range(W):
                    if board[x, y] < 0:
                        pos = (x, y)
                        break
                if pos is not None:
                    break

            if pos is None:
                searched[0] += 1
                score_solution()
                return

            x, y = pos
            for idx in order:
                if used[idx]:
                    continue
                p = pieces[idx][0]
                h, w = p.shape
                if x + h <= H and y + w <= W and np.all(board[x:x + h, y:y + w] < 0):
                    board[x:x + h, y:y + w] = idx
                    used[idx] = True
                    placed.append((idx, x, y))
                    backtrack()
                    placed.pop()
                    used[idx] = False
                    board[x:x + h, y:y + w] = -1

        backtrack()

    return best_out if best_out is not None else g.copy()

def transform(grid):
    bg = np.bincount(grid.ravel(), minlength=10).argmax()
    h, w = grid.shape

    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if seen[r, c] or grid[r, c] == bg:
                continue

            color = grid[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            cells = []

            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if (
                            0 <= nx < h and 0 <= ny < w
                            and not seen[nx, ny]
                            and grid[nx, ny] == color
                        ):
                            seen[nx, ny] = True
                            stack.append((nx, ny))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append({
                "color": color,
                "cells": cells,
                "r0": min(rs),
                "r1": max(rs),
                "c0": min(cs),
                "c1": max(cs),
            })

    zero_comps = [c for c in comps if c["color"] == 0]
    panel = max(zero_comps, key=lambda c: len(c["cells"]))

