            inside_panel = (
                pr0 <= comp["r0"] <= pr1 and pr0 <= comp["r1"] <= pr1
                and pc0 <= comp["c0"] <= pc1 and pc0 <= comp["c1"] <= pc1
            )
            if not inside_panel:
                count += 1

        for i in range(count):
            col = mc + 2 * i
            if col < out.shape[1]:
                out[mr, col] = color

    return out

def transform(grid):
