def transform(grid):
    g = grid
    H, W = g.shape
    nz = (g != 0).astype(int)

    pref = np.zeros((H + 1, W + 1), dtype=int)
    pref[1:, 1:] = nz.cumsum(0).cumsum(1)

    def rect_count(r, c, s):
        return pref[r + s, c + s] - pref[r, c + s] - pref[r + s, c] + pref[r, c]

    best = None
    for s in range(1, min(H, W) + 1):
        area_penalty = 0.12 * s * s
        for r in range(H - s + 1):
            for c in range(W - s + 1):
                cnt = rect_count(r, c, s)
                if cnt == 0:
                    continue
                score = cnt - area_penalty
                if best is None or score > best[0]:
                    best = (score, r, c, s)

    _, r0, c0, n = best
    crop = g[r0:r0 + n, c0:c0 + n]
    out = np.zeros_like(crop)

    def apply_op(mask, op):
        if op == "h":
            return mask[:, ::-1]
        if op == "v":
            return mask[::-1, :]
        if op == "r180":
            return mask[::-1, ::-1]
        if op == "cw":
            return np.rot90(mask, -1)
        if op == "ccw":
            return np.rot90(mask, 1)
        return mask

    colors = [x for x in np.unique(crop) if x != 0]

    for color in colors:
        mask = (crop == color)
        outside = (g == color).copy()
        outside[r0:r0 + n, c0:c0 + n] = False
        pts = np.argwhere(outside)

        op = "id"
        if len(pts):
            rr0, cc0 = pts.min(axis=0)
            rr1, cc1 = pts.max(axis=0)
            h = rr1 - rr0 + 1
            w = cc1 - cc0 + 1
            cy = (rr0 + rr1) / 2
            cx = (cc0 + cc1) / 2
            cnt = int(mask.sum())

            if h == 1 and w > 1:
                op = "ccw" if cy < r0 else "id"
            elif w == 1 and h > 1:
                op = "ccw" if cy < r0 else "r180"
            elif h == 1 and w == 1:
                if cy < r0:
                    op = "v"
                elif cy >= r0 + n and cx < c0:
                    if n >= 13 and cnt > 20:
                        op = "cw"
                    elif cnt <= 6:
                        op = "v"
                    else:
                        op = "h"

        out[apply_op(mask, op)] = color

    return out

def transform(grid):
    h, w = grid.shape
    nz = [(r, c) for r in range(h) for c in range(w) if grid[r, c] != 0]

    seen = set()
    clusters = []
    nzset = set(nz)

    for start in nz:
        if start in seen:
            continue
        stack = [start]
        seen.add(start)
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for rr in range(max(0, r - 2), min(h, r + 3)):
                for cc in range(max(0, c - 2), min(w, c + 3)):
                    if (rr, cc) in nzset and (rr, cc) not in seen:
                        seen.add((rr, cc))
                        stack.append((rr, cc))
        clusters.append(comp)

    def box(cells):
        rs = [p[0] for p in cells]
        cs = [p[1] for p in cells]
        return min(rs), min(cs), max(rs), max(cs)

    main = max(clusters, key=lambda c: (len(c), (box(c)[2] - box(c)[0] + 1) * (box(c)[3] - box(c)[1] + 1)))
    r0, c0, r1, c1 = box(main)
    crop = grid[r0:r1 + 1, c0:c1 + 1]
    oh, ow = crop.shape
    out = np.zeros_like(crop)

    colors = [x for x in np.unique(grid) if x != 0]

    def outside_cells(color):
        return [(r, c) for r in range(h) for c in range(w)
                if grid[r, c] == color and not (r0 <= r <= r1 and c0 <= c <= c1)]

    def apply_op(mask, op):
        if op == "id":
            return mask
        if op == "ud":
            return np.flipud(mask)
        if op == "lr":
            return np.fliplr(mask)
        if op == "r90":
            return np.rot90(mask, 1)
        if op == "r180":
            return np.rot90(mask, 2)
        if op == "r270":
            return np.rot90(mask, 3)
        return mask

    for color in colors:
        mask = (crop == color)
        if not mask.any():
            continue

        clues = outside_cells(color)
        op = "id"

        if clues:
            ar0, ac0, ar1, ac1 = box(clues)
            ch = ar1 - ar0 + 1
            cw = ac1 - ac0 + 1
            cr = (ar0 + ar1) / 2.0
            cc = (ac0 + ac1) / 2.0
            mr = (r0 + r1) / 2.0
            mc = (c0 + c1) / 2.0
            dr = cr - mr
            dc = cc - mc

            if ch > cw:
                op = "r180"
            elif cw > ch:
                op = "r90" if cr < r0 else "id"
            else:
                rs, cs = np.where(mask)
                touches_edge = (
                    rs.min() == 0 or rs.max() == oh - 1 or
                    cs.min() == 0 or cs.max() == ow - 1
                )
                if touches_edge and abs(dr) > 0 and abs(dc) > 0:
                    if dr < 0 and dc > 0:
                        op = "r90"
                    elif dr > 0 and dc < 0:
                        op = "r270"
                    elif dr < 0 and dc < 0:
                        op = "r180"
                    else:
                        op = "id"
                else:
                    op = "ud" if abs(dr) >= abs(dc) else "lr"

        moved = apply_op(mask, op)
        out[moved] = color

    return out

def transform(grid):
    bg = np.bincount(grid.ravel(), minlength=10).argmax()
    vals = [v for v in np.unique(grid) if v != bg]
    if not vals:
        return grid.copy()
    col = vals[0]

    h, w = grid.shape
    fg = grid == col
    out = np.full_like(grid, bg)

    orth = np.zeros_like(fg, dtype=bool)
    orth[:, 1:] |= fg[:, 1:] & fg[:, :-1]
    orth[:, :-1] |= fg[:, :-1] & fg[:, 1:]
    orth[1:, :] |= fg[1:, :] & fg[:-1, :]
    orth[:-1, :] |= fg[:-1, :] & fg[1:, :]

    diag = np.zeros_like(fg, dtype=bool)
    for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
        a = fg[max(0, dr):h + min(0, dr), max(0, dc):w + min(0, dc)]
        b = diag[max(0, -dr):h - max(0, dr), max(0, -dc):w - max(0, dc)]
        b |= a

    major_row = np.zeros(h, dtype=bool)
    for r in range(h):
        run = 0
        for c in range(w):
            if fg[r, c]:
                run += 1
                if run >= 3:
                    major_row[r] = True
            else:
                run = 0

    major_col = np.zeros(w, dtype=bool)
    for c in range(w):
        run = 0
        for r in range(h):
            if fg[r, c]:
                run += 1
                if run >= 3:
                    major_col[c] = True
            else:
                run = 0

    keep = orth | (fg & ~diag & (major_row[:, None] | major_col[None, :]))
    out[keep] = col

    def row_support(r, a, b):
        for rr in (r - 1, r + 1):
            if 0 <= rr < h:
                if a + 1 < w and fg[rr, a + 1]:
                    return True
                if b - 1 >= 0 and fg[rr, b - 1]:
                    return True
        return False

    def col_support(c, a, b):
        for rr in (a, a + 1, b - 1, b):
            if 0 <= rr < h:
                for cc in range(max(0, c - 2), min(w, c + 3)):
                    if cc != c and fg[rr, cc]:
                        return True
        return False

    for r in range(h):
        xs = np.flatnonzero(out[r] == col)
        if len(xs) < 2:
            continue
        for a, b in zip(xs[:-1], xs[1:]):
            if 1 < b - a <= 4 and row_support(r, a, b):
                out[r, a:b + 1] = col

    for c in range(w):
        ys = np.flatnonzero(out[:, c] == col)
        if len(ys) < 2:
            continue
        for a, b in zip(ys[:-1], ys[1:]):
            if 1 < b - a <= 5 and col_support(c, a, b):
                out[a:b + 1, c] = col

    return out

def transform(grid):
    g = np.array(grid, copy=True)
    out = g.copy()
    h, w = g.shape

    vals, counts = np.unique(g, return_counts=True)
    bg = vals[np.argmax(counts)]
    colors = [v for v in vals if v != bg]

    for color in colors:
        removed = np.zeros((h, w), dtype=bool)

        for r in range(h):
            for c in range(w):
                if g[r, c] != color:
                    continue

                orth = False
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w and g[rr, cc] == color:
                        orth = True
                        break

                diag = False
                for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w and g[rr, cc] == color:
                        diag = True
                        break

                if diag and not orth:
                    removed[r, c] = True

        out[removed] = bg

        def runs(seq):
            res = []
            i = 0
            n = len(seq)
            while i < n:
                if seq[i]:
                    j = i
                    while j + 1 < n and seq[j + 1]:
                        j += 1
                    res.append((i, j, j - i + 1))
                    i = j + 1
                else:
                    i += 1
            return res

        # Complete horizontal gaps where removed diagonal pixels indicate a bent line.
        for r in range(h):
            rs = runs(out[r] == color)
            for a, b in zip(rs, rs[1:]):
                gap1, gap2 = a[1] + 1, b[0] - 1
                gap = gap2 - gap1 + 1
                if gap <= 0 or gap > 4:
                    continue

                evidence = False
                for rr in range(h):
                    if evidence:
                        break
                    for cc in range(gap1, gap2 + 1):
                        if removed[rr, cc]:
                            if abs(rr - r) <= 1 or a[2] >= 4 or b[2] >= 4:
                                evidence = True
                                break

                if evidence:
                    out[r, gap1:gap2 + 1] = color

        # Complete vertical gaps by the same rule.
        for c in range(w):
            cs = runs(out[:, c] == color)
            for a, b in zip(cs, cs[1:]):
                gap1, gap2 = a[1] + 1, b[0] - 1
                gap = gap2 - gap1 + 1
                if gap <= 0 or gap > 4:
                    continue

                evidence = False
                for rr in range(gap1, gap2 + 1):
                    if evidence:
                        break
                    for cc in range(w):
                        if removed[rr, cc]:
                            if abs(cc - c) <= 1 or a[2] >= 4 or b[2] >= 4:
                                evidence = True
                                break

                if evidence:
                    out[gap1:gap2 + 1, c] = color

    return out

def transform(grid):
    g = grid.copy()
    h, w = g.shape

    vals, counts = np.unique(g, return_counts=True)
    bg = vals[np.argmax(counts)]
    colors = vals[vals != bg]
    if len(colors) == 0:
        return g
    col = colors[np.argmax([np.sum(g == c) for c in colors])]

    mask = (g == col)

    # Find likely true straight strokes: rows/columns with several colored cells.
    row_counts = mask.sum(axis=1)
    col_counts = mask.sum(axis=0)
    row_lines = row_counts >= 3
    col_lines = col_counts >= 3

    out = np.full_like(g, bg)

    # Preserve and complete horizontal strokes across their span.
    for r in range(h):
        if row_lines[r]:
            cs = np.where(mask[r])[0]
            if len(cs):
                out[r, cs.min():cs.max() + 1] = col

    # Preserve and complete vertical strokes across their span.
    for c in range(w):
        if col_lines[c]:
            rs = np.where(mask[:, c])[0]
            if len(rs):
                out[rs.min():rs.max() + 1, c] = col

    # For long vertical lines that are separated by diagonal detours, extend through
    # nearby aligned endpoints while avoiding very large unrelated gaps.
    for c in range(w):
        rs = np.where(mask[:, c])[0]
        if len(rs) >= 3:
            groups = []
            start = prev = rs[0]
            for r in rs[1:]:
                if r == prev + 1:
                    prev = r
                else:
                    groups.append((start, prev))
                    start = prev = r
            groups.append((start, prev))

            kept = [grp for grp in groups if grp[1] - grp[0] + 1 >= 2]
            for a, b in zip(kept, kept[1:]):
                gap = b[0] - a[1] - 1
                if 0 < gap <= 3:
                    out[a[1]:b[0] + 1, c] = col

    return out

def transform(grid):
    bg = grid[0, 0]
    h, w = grid.shape
    out = grid.copy()

    visited = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if visited[r, c] or grid[r, c] == bg:
                continue
            color = grid[r, c]
            stack = [(r, c)]
            visited[r, c] = True
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and grid[nr, nc] == color:
                        visited[nr, nc] = True
                        stack.append((nr, nc))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append({
                "color": int(color),
                "cells": cells,
                "r0": min(rs),
                "r1": max(rs),
                "c0": min(cs),
                "c1": max(cs),
                "rc": (min(rs) + max(rs)) / 2,
                "cc": (min(cs) + max(cs)) / 2,
            })

    markers = [c for c in comps if c["r0"] == c["r1"] and len(c["cells"]) >= 3]
    objects = [c for c in comps if c not in markers]

    for m in markers:
        for r, c in m["cells"]:
            out[r, c] = bg

    if not objects:
        return out

    tops = sorted(set(o["r0"] for o in objects))
    diffs = [b - a for a, b in zip(tops, tops[1:]) if b > a]
    if diffs:
        row_step = min(diffs)
    else:
        row_step = max(o["r1"] - o["r0"] + 1 for o in objects) + 1

    col_centers = sorted(set(o["cc"] for o in objects))

    def nearest_col(x):
        return min(col_centers, key=lambda y: abs(y - x))

    red_cols = {nearest_col(m["cc"]) for m in markers if m["color"] == 2}
    green_cols = {nearest_col(m["cc"]) for m in markers if m["color"] == 3}

    red_count = sum(1 for o in objects if nearest_col(o["cc"]) in red_cols)

    for o in objects:
        col = nearest_col(o["cc"])
        if col in red_cols:
            for r, c in o["cells"]:
                out[r, c] = 5

    for o in objects:
        col = nearest_col(o["cc"])
        if col in green_cols:
            for k in range(1, red_count + 1):
                shift = row_step * k
                for r, c in o["cells"]:
                    nr = r - shift
                    if 0 <= nr < h:
                        out[nr, c] = o["color"]

    return out

def transform(grid):
    out = grid.copy()
    h, w = out.shape
    bg = int(np.bincount(out.ravel()).argmax())

    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if seen[r, c] or out[r, c] == bg:
                continue

            color = int(out[r, c])
            stack = [(r, c)]
            seen[r, c] = True
            cells = []

            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and out[nr, nc] != bg:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append({
                "cells": cells,
                "color": color,
                "top": min(rs),
                "bottom": max(rs),
                "left": min(cs),
                "right": max(cs),
                "height": max(rs) - min(rs) + 1,
                "width": max(cs) - min(cs) + 1,
            })

    markers = [c for c in comps if c["height"] == 1 and c["bottom"] == h - 1]
    stamps = [c for c in comps if c["height"] > 1]

    marker2 = None
    marker3 = None
    for m in markers:
        if m["color"] == 2:
            marker2 = m
        elif m["color"] == 3:
            marker3 = m

    if marker2 is None or marker3 is None:
        return out

    for m in markers:
        for r, c in m["cells"]:
            out[r, c] = bg

    col2 = marker2["left"]
    col3 = marker3["left"]

    stamps2 = [s for s in stamps if s["left"] == col2]
    stamps3 = [s for s in stamps if s["left"] == col3]

    for s in stamps2:
        for r, c in s["cells"]:
            out[r, c] = 5

    if stamps3 and stamps2:
        tops = sorted(set(s["top"] for s in stamps))
        diffs = [tops[i + 1] - tops[i] for i in range(len(tops) - 1) if tops[i + 1] > tops[i]]
        step = min(diffs) if diffs else 4

        base = min(stamps3, key=lambda s: s["top"])
        mask = [(r - base["top"], c - base["left"]) for r, c in base["cells"]]
        color = base["color"]
        top = base["top"]

        for k in range(len(stamps2)):
            ntop = top - step * (k + 1)
            for dr, dc in mask:
                rr, cc = ntop + dr, col3 + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr, cc] = color

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    sep_rows = [r for r in range(h) if np.all(grid[r] == 6)]
    first_sep = sep_rows[0]
    second_sep = sep_rows[-1]

    def row_bands(r0, r1):
        rows = []
        for r in range(r0, r1):
            if np.any((grid[r] != 8) & (grid[r] != 6)):
                rows.append(r)
        bands = []
        if not rows:
            return bands
        start = prev = rows[0]
        for r in rows[1:]:
            if r == prev + 1:
                prev = r
            else:
                bands.append((start, prev))
                start = prev = r
        bands.append((start, prev))
        return bands

    table_rows = row_bands(first_sep + 1, second_sep)
    top_rows = row_bands(0, first_sep)[0]

    used_cols = []
    for c in range(w):
        found = False
        for rs, re in table_rows:
            if np.any((grid[rs:re + 1, c] != 8) & (grid[rs:re + 1, c] != 6)):
                found = True
                break
        if found:
            used_cols.append(c)

    col_bands = []
    start = prev = used_cols[0]
    for c in used_cols[1:]:
        if c == prev + 1:
            prev = c
        else:
            col_bands.append((start, prev))
            start = prev = c
    col_bands.append((start, prev))

    nrows, ncols = len(table_rows), len(col_bands)

    def slot(rband, cband):
        rs, _ = rband
        cs, _ = cband
        return grid[rs:rs + 3, cs:cs + 3]

    table = [[slot(table_rows[i], col_bands[j]) for j in range(ncols)]
             for i in range(nrows)]

    queries = []
    for j, cb in enumerate(col_bands):
        q = slot(top_rows, cb)
        if np.any(q != 8):
            queries.append((j, q))

    candidates = []
    for _, q in queries:
        opts = []
        for i in range(nrows):
            for j in range(ncols):
                if table[i][j].shape == q.shape and np.array_equal(table[i][j], q):
                    opts.append((i, j))
        if opts:
            candidates.append(opts)

    best = []

    def score(choice):
        uniq = []
        for p in choice:
            if p not in uniq:
                uniq.append(p)
        row_counts = [sum(1 for p in uniq if p[0] == i) for i in range(nrows)]
        col_counts = [sum(1 for p in uniq if p[1] == j) for j in range(ncols)]
        complete = int(max(row_counts + col_counts) >= min(nrows, ncols))
        return (complete, max(row_counts + col_counts), len(uniq))

    def search(k, cur):
        nonlocal best
        if k == len(candidates):
            if not best or score(cur) > score(best):
                best = cur[:]
            return
        for p in candidates[k]:
            cur.append(p)
            search(k + 1, cur)
            cur.pop()

    search(0, [])

    chosen = []
    for p in best:
        if p not in chosen:
            chosen.append(p)

    row_counts = [sum(1 for p in chosen if p[0] == i) for i in range(nrows)]
    col_counts = [sum(1 for p in chosen if p[1] == j) for j in range(ncols)]

    complete_kind = None
    complete_index = None
    if row_counts and max(row_counts) == ncols:
        complete_kind = "row"
        complete_index = row_counts.index(ncols)
    elif col_counts and max(col_counts) == nrows:
        complete_kind = "col"
        complete_index = col_counts.index(nrows)

    def mark_cell(i, j):
        rs, _ = table_rows[i]
        cs, _ = col_bands[j]
        for r in range(max(0, rs - 1), min(h, rs + 4)):
            for c in range(max(0, cs - 1), min(w, cs + 4)):
                if out[r, c] == 8:
                    out[r, c] = 3

    if complete_kind == "row":
        for j in range(ncols):
            mark_cell(complete_index, j)
    elif complete_kind == "col":
        for i in range(nrows):
            mark_cell(i, complete_index)
    else:
        for i, j in chosen:
            mark_cell(i, j)

    fill_color = 3 if complete_kind else 2
    if sep_rows:
        out[second_sep + 1:h, :] = fill_color

    if complete_kind:
        for r in range(0, first_sep):
            for c in range(w):
                if out[r, c] == 8:
                    out[r, c] = 3

    if complete_kind == "row":
        match_by_query_pos = {}
        for idx, (pos, _) in enumerate(queries):
            if idx < len(best):
                match_by_query_pos[pos] = best[idx]
        trs, _ = top_rows
        for pos, matched in match_by_query_pos.items():
            if matched == (complete_index, pos) and complete_index + 1 < nrows:
                repl = table[complete_index + 1][pos]
                cs, _ = col_bands[pos]
                for dr in range(3):
                    for dc in range(3):
                        out[trs + dr, cs + dc] = repl[dr, dc] if repl[dr, dc] != 8 else 3

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape
    bg = 8

    sep_rows = []
    for r in range(h):
        vals = set(int(x) for x in grid[r])
        if len(vals) == 1 and list(vals)[0] != bg:
            sep_rows.append(r)

    sep1 = sep_rows[0]
    sep2 = sep_rows[1] if len(sep_rows) > 1 else h

    def clusters(vals):
        vals = sorted(vals)
        if not vals:
            return []
        res = [[vals[0], vals[0]]]
        for v in vals[1:]:
            if v == res[-1][1] + 1:
                res[-1][1] = v
            else:
                res.append([v, v])
        return res

    table_rows = range(sep1 + 1, sep2)
    used_cols = set()
    used_rows = set()
    for r in table_rows:
        for c in range(w):
            if grid[r, c] != bg:
                used_cols.add(c)
                used_rows.add(r)

    xstarts = [a for a, b in clusters(used_cols)]
    ystarts = [a for a, b in clusters(used_rows)]

    top_used_rows = set()
    for r in range(sep1):
        for c in range(w):
            if grid[r, c] != bg:
                top_used_rows.add(r)
    top_start = clusters(top_used_rows)[0][0] if top_used_rows else 1

    def cell_sig(r0, c0):
        patch = grid[r0:r0 + 3, c0:c0 + 3]
        nz = patch[patch != bg]
        if nz.size == 0:
            return None
        color = int(nz[0])
        pat = tuple(tuple(1 if int(patch[i, j]) != bg else 0 for j in range(3)) for i in range(3))
        return (color, pat)

    top_sigs = set()
    for c0 in xstarts:
        sig = cell_sig(top_start, c0)
        if sig is not None:
            top_sigs.add(sig)

    selected = []
    for ri, r0 in enumerate(ystarts):
        for ci, c0 in enumerate(xstarts):
            if cell_sig(r0, c0) in top_sigs:
                selected.append((ri, ci, r0, c0))

    nrows, ncols = len(ystarts), len(xstarts)
    full_row = None
    full_col = None
    for ri in range(nrows):
        if sum(1 for x in selected if x[0] == ri) == ncols:
            full_row = ri
    for ci in range(ncols):
        if sum(1 for x in selected if x[1] == ci) == nrows:
            full_col = ci

    is_full_line = full_row is not None or full_col is not None

    for _, _, r0, c0 in selected:
        r1, r2 = max(0, r0 - 1), min(h, r0 + 4)
        c1, c2 = max(0, c0 - 1), min(w, c0 + 4)
        mask = out[r1:r2, c1:c2] == bg
        out[r1:r2, c1:c2][mask] = 3

    if is_full_line:
        mask = out[:sep1, :] == bg
        out[:sep1, :][mask] = 3

    if full_row is not None and full_row + 1 < nrows and full_row < ncols:
        src_r = ystarts[full_row + 1]
        src_c = xstarts[full_row]
        dst_c = xstarts[full_row]
        out[top_start:top_start + 3, dst_c:dst_c + 3] = grid[src_r:src_r + 3, src_c:src_c + 3]

    fill = 3 if is_full_line else 2
    if sep2 + 1 < h:
        out[sep2 + 1:, :] = fill

    return out

def transform(grid):
    out = grid.copy()
    h, w = grid.shape

    vals, counts = np.unique(grid, return_counts=True)
    bg = vals[np.argmax(counts)]

    def runs(xs):
        xs = sorted(xs)
        if not xs:
            return []
        res = []
        a = b = xs[0]
        for x in xs[1:]:
            if x == b + 1:
                b = x
            else:
                res.append((a, b))
                a = b = x
        res.append((a, b))
        return res

    sep_rows = [r for r in range(h) if np.all(grid[r] == grid[r, 0]) and grid[r, 0] != bg]
    first_sep, last_sep = sep_rows[0], sep_rows[-1]

    board_area = range(first_sep + 1, last_sep)
    row_groups = runs([r for r in board_area if np.any(grid[r] != bg)])
    col_groups = runs([c for c in range(w) if np.any(grid[first_sep + 1:last_sep, c] != bg)])

    top_rows = runs([r for r in range(first_sep) if np.any(grid[r] != bg)])
    calls = []
    if top_rows:
        tr0, tr1 = top_rows[0]
        for c0, c1 in col_groups:
            p = grid[tr0:tr1 + 1, c0:c1 + 1]
            if np.any(p != bg):
                calls.append(p.copy())

    def norm(obj):
        mask = obj != bg
        colors = obj[mask]
        if colors.size == 0:
            return None
        cs, ns = np.unique(colors, return_counts=True)
        color = cs[np.argmax(ns)]
        return color, (obj == color)

    def variants(mask):
        res = []
        for k in range(4):
            r = np.rot90(mask, k)
            res.append(r)
            res.append(np.fliplr(r))
        return res

    call_norms = []
    for p in calls:
        n = norm(p)
        if n is not None:
            color, mask = n
            call_norms.append((color, variants(mask)))

    marked = []
    for i, (r0, r1) in enumerate(row_groups):
        row = []
        for j, (c0, c1) in enumerate(col_groups):
            cell = grid[r0:r1 + 1, c0:c1 + 1]
            cn = norm(cell)
            hit = False
            if cn is not None:
                color, cmask = cn
                for pcolor, pmasks in call_norms:
                    if pcolor == color:
                        for pm in pmasks:
                            if pm.shape == cmask.shape and np.array_equal(pm, cmask):
                                hit = True
                                break
                    if hit:
                        break
            row.append(hit)
            if hit:
                rr0, rr1 = max(0, r0 - 1), min(h, r1 + 2)
                cc0, cc1 = max(0, c0 - 1), min(w, c1 + 2)
                sub = out[rr0:rr1, cc0:cc1]
                sub[sub == bg] = 3
        marked.append(row)

    row_bingos = [i for i, row in enumerate(marked) if row and all(row)]
    col_bingos = []
    if marked:
        for j in range(len(marked[0])):
            if all(marked[i][j] for i in range(len(marked))):
                col_bingos.append(j)

    bingo = bool(row_bingos or col_bingos)

    if bingo:
        top = out[:first_sep]
        top[top == bg] = 3

        if row_bingos and not col_bingos and top_rows:
            i = row_bingos[0]
            if i + 1 < len(row_groups) and i < len(col_groups):
                sr0, sr1 = row_groups[i + 1]
                tc0, tc1 = col_groups[i]
                cell = grid[sr0:sr1 + 1, tc0:tc1 + 1]
                tr0, tr1 = top_rows[0]
                target = out[tr0:tr1 + 1, tc0:tc1 + 1]
                target[:, :] = 3
                mask = cell != bg
                target[mask] = cell[mask]

    out[last_sep + 1:] = 3 if bingo else 2
    return out
